# lc103 (9.69.0): the Moment Finder and the Showbar in the Creator Studio, and the same moments inside Game-to-Script. Real Chromium, real Stockfish on the device, a real game
# (Morphy's Opera Game). Checks: every kind of moment is found and explained; the Showbar sits in the free band under the record bar and
# never moves the record bar or shrinks the stage; a chip, ] and [ jump the Studio board; type toggles, fold, order; Game-to-Script hands over;
# a mistake becomes a video project; the scan is back after a reload; the phone layout has no sideways scroll and 44 px targets.
APP = 'http://127.0.0.1:8765/app.html'
OWNER = "localStorage.setItem('lc26-auth', JSON.stringify({ access_token: 'x', refresh_token: '', exp: Date.now() + 36e5, email: 'lanckrietchess@gmail.com' }))"
_SR = "(() => { const h = [...document.querySelectorAll('*')].find(e => e.shadowRoot && e.shadowRoot.getElementById('stage')); return h ? h.shadowRoot : null; })()"
def st(pg, js): return pg.evaluate("(async () => { const R = " + _SR + "; if (!R) return 'no studio'; " + js + " })()")
OPERA = '[Event "Paris"]\n[White "Paul Morphy"]\n[Black "Duke Karl / Count Isouard"]\n[Result "1-0"]\n\n1. e4 e5 2. Nf3 d6 3. d4 Bg4 4. dxe5 Bxf3 5. Qxf3 dxe5 6. Bc4 Nf6 7. Qb3 Qe7 8. Nc3 c6 9. Bg5 b5 10. Nxb5 cxb5 11. Bxb5+ Nbd7 12. O-O-O Rd8 13. Rxd7 Rxd7 14. Rd1 Qe6 15. Bxd7+ Nxd7 16. Qb8+ Nxb8 17. Rd8# 1-0'
TRAP = '[Event "Test"]\n[White "Student"]\n[Black "Coach"]\n[Result "0-1"]\n\n1. e4 e5 2. Nf3 Nc6 3. Bc4 Nd4 4. Nxe5 Qg5 5. Nxf7 Qxg2 6. Rf1 Qxe4+ 7. Be2 Nf3# 0-1'
RECT = "(s) => { const e = R.querySelector(s); if (!e) return null; const r = e.getBoundingClientRect(); return [Math.round(r.left), Math.round(r.top), Math.round(r.width), Math.round(r.height)]; }"
def rects(pg): return st(pg, "const f = " + RECT + "; return {stage: f('#stage'), dock: f('#lc54-dock'), bar: f('#lc103-sb'), vh: innerHeight, vw: innerWidth}")
def boot(pg):
    pg.goto('http://127.0.0.1:8765/version.json'); pg.evaluate(OWNER); pg.evaluate("localStorage.setItem('lc31-format', JSON.stringify({id: 'short', at: Date.now()}))")
    pg.goto(APP + '#studio'); pg.wait_for_function("!!(" + _SR + ")", timeout=30000); pg.wait_for_timeout(3500)
    pg.evaluate("document.querySelectorAll('.sheet-wrap [data-close]').forEach(b => b.click())")
    st(pg, "const f = R.querySelector('.lc31-fmt'); if (f) f.click(); return 1"); pg.wait_for_timeout(500)
    st(pg, "R.querySelector('[data-mb-tab=shoot]').click(); return 1"); pg.wait_for_timeout(1500)
with sync_playwright() as p:
    br = p.chromium.launch(args=['--use-fake-ui-for-media-stream', '--use-fake-device-for-media-stream'])
    c = mkctx(br, 1280, 800); pg = c.new_page(); watch(pg, 'lc103-desktop'); boot(pg)
    out('menu [Moments button, before a scan: no Showbar]', [st(pg, "const b = R.querySelector('[data-mb=moments]'); return b ? b.textContent : null"), st(pg, "const b = R.querySelector('#lc103-sb'); return !b || b.hidden")])
    before = rects(pg)
    st(pg, "R.querySelector('[data-mb=moments]').click(); return 1"); pg.wait_for_timeout(600)
    out('finder [opens, title, sources]', [pg.evaluate("!!document.getElementById('lc103-ui')"), pg.evaluate("document.querySelector('#lc103-ui h2').textContent"), pg.evaluate("[...document.querySelectorAll('#lc103-ui [data-m]')].map(b => b.getAttribute('data-m')).filter(x => /run|theirs|board|mine|lib|g2s/.test(x))")])
    pg.fill('#lc103-ui textarea[data-f=pgn]', OPERA); pg.select_option('#lc103-ui select[data-f=depth]', 'fast'); pg.select_option('#lc103-ui select[data-f=side]', 'both')
    pg.click('#lc103-ui [data-m=run]'); pg.wait_for_timeout(5000)
    live = pg.evaluate("[LC103.cur() && !LC103.cur().done, document.querySelector('#lc103-ui [data-st]').textContent.slice(0, 15)]")
    pg.wait_for_function("LC103.cur() && LC103.cur().done", timeout=240000); pg.wait_for_timeout(800)
    out('scan running [not done yet, status]', live)
    M = pg.evaluate("LC103.cur().moments.map(m => ({i: m.i, san: m.san, num: m.num, color: m.color, types: m.types, score: m.score, reason: m.reason, form: m.form}))")
    types = sorted(set(t for m in M for t in m['types']))
    out('scan [plies, 5+ moments, brilliant and great found]', [pg.evaluate("LC103.cur().n"), len(M) >= 5, 'brilliant' in types and 'great' in types])
    print('info kinds found:', types, len(M))
    out('brilliant [Qb8+ found as brilliant]', any(m['san'] == 'Qb8+' and 'brilliant' in m['types'] for m in M))
    out('every moment [score 0-100, one-line reason, English, form]', [all(0 <= m['score'] <= 100 for m in M), all(len(m['reason']) > 20 and '\n' not in m['reason'] for m in M), all(all(ord(ch) < 0x2500 or ch in '—–…' for ch in m['reason']) for m in M), set(m['form'] for m in M) <= {'short', 'mid'}])
    out('finder list [rows, filter toggles, clip plan button]', [pg.evaluate("document.querySelectorAll('#lc103-ui .m-it').length") == len(M), pg.evaluate("document.querySelectorAll('#lc103-ui .m-t').length"), pg.evaluate("/Copy clip plan/.test(document.querySelector('#lc103-ui [data-m=plan]').textContent)")])
    out('finder order [best clips first]', pg.evaluate("(() => { const s = [...document.querySelectorAll('#lc103-ui .m-it .m-sc')].map(e => +e.textContent.replace(/[^0-9]/g, '')); return s.every((v, i) => !i || v <= s[i - 1]); })()"))
    pg.click('#lc103-ui [data-m=showbar]'); pg.wait_for_timeout(1500)
    after = rects(pg)
    out('layer closed, Showbar shown', [pg.evaluate("!document.getElementById('lc103-ui')"), st(pg, "return !R.querySelector('#lc103-sb').hidden")])
    out('stage and record bar untouched [stage same, dock same]', [before['stage'] == after['stage'], before['dock'] == after['dock']])
    b, d, s = after['bar'], after['dock'], after['stage']
    out('Showbar place [under the record bar, inside the screen, not over the stage, height]', [b[1] >= d[1] + d[3], b[1] + b[3] <= after['vh'], b[1] >= s[1] + s[3], b[3]])
    out('Showbar chips [one per moment, reason line, badges]', [st(pg, "return R.querySelectorAll('#lc103-sb .sb-i').length") == len(M), st(pg, "return R.querySelector('#lc103-sb .sb-i .sb-l2').textContent.length > 20"), st(pg, "return R.querySelectorAll('#lc103-sb .sb-p').length")])
    out('not in the recording [Showbar is page UI, not on the stage canvas]', st(pg, "return !R.querySelector('#stage').contains(R.querySelector('#lc103-sb'))"))
    q = next(m for m in M if m['san'] == 'Qb8+')
    st(pg, "R.querySelector('#lc103-sb .sb-i[data-i=\"%d\"]').click(); return 1" % q['i']); pg.wait_for_timeout(600)
    out('chip jump [board on the position before Qb8+, side to move, active chip]', [pg.evaluate("LanckrietStudio.board.idx") == q['i'], pg.evaluate("LanckrietStudio.board.orient"), st(pg, "return R.querySelector('#lc103-sb .sb-i.on').getAttribute('data-i')") == str(q['i'])])
    order = sorted(M, key=lambda m: m['i']); k = [m['i'] for m in order].index(q['i'])
    pg.keyboard.press('['); pg.wait_for_timeout(400); n1 = pg.evaluate("LanckrietStudio.board.idx")
    pg.keyboard.press(']'); pg.wait_for_timeout(400); n2 = pg.evaluate("LanckrietStudio.board.idx")
    out('keys [ ] [back, next]', [n1 == order[k - 1]['i'], n2 == q['i']])
    out('old game strip hidden while the Showbar shows [strip, stage same]', [st(pg, "const g = R.querySelector('#lc31-game'); return !g || getComputedStyle(g).display"), rects(pg)['stage'] == before['stage']])
    nb = sum(1 for m in M if 'brilliant' not in m['types'] or len(m['types']) > 1)
    st(pg, "R.querySelector('#lc103-sb .sb-p[data-t=brilliant]').click(); return 1"); pg.wait_for_timeout(300)
    vis = st(pg, "return R.querySelectorAll('#lc103-sb .sb-i').length")
    st(pg, "R.querySelector('#lc103-sb .sb-p[data-t=brilliant]').click(); return 1"); pg.wait_for_timeout(300)
    out('type toggle [Brilliant off hides only-brilliant moments, back on]', [vis == nb, st(pg, "return R.querySelectorAll('#lc103-sb .sb-i').length") == len(M)])
    st(pg, "R.querySelector('#lc103-sb [data-sb=set]').click(); return 1"); pg.wait_for_timeout(300)
    st(pg, "const s = R.querySelector('#lc103-pop select[data-pp=order]'); s.value = 'score'; s.dispatchEvent(new Event('change', {bubbles: true})); return 1"); pg.wait_for_timeout(300)
    out('settings [order: best clips first on the Showbar]', st(pg, "const s = [...R.querySelectorAll('#lc103-sb .sb-i em')].map(e => +e.textContent.replace(/[^0-9]/g, '')); return s.every((v, i) => !i || v <= s[i - 1])"))
    st(pg, "R.querySelector('#lc103-pop [data-pp=plan]').click(); return 1"); pg.wait_for_timeout(300)
    out('clip plan [one line per moment, no rating promise]', pg.evaluate("(() => { const t = LC103.plan(); return [t.split('\\n').filter(l => /^#\\d+ /.test(l)).length === LC103.cur().moments.length, /nothing here is a promise of a rating/.test(t)]; })()"))
    st(pg, "const s = R.querySelector('#lc103-pop select[data-pp=order]'); s.value = 'game'; s.dispatchEvent(new Event('change', {bubbles: true})); R.querySelector('#lc103-sb [data-sb=set]').click(); return 1"); pg.wait_for_timeout(200)
    st(pg, "R.querySelector('#lc103-sb [data-sb=fold]').click(); return 1"); pg.wait_for_timeout(300)
    f = rects(pg)
    out('fold [one small pill, record bar and stage still the same]', [f['bar'][2] < 600, f['dock'] == before['dock'], f['stage'] == before['stage']])
    st(pg, "R.querySelector('#lc103-sb [data-sb=unfold]').click(); return 1"); pg.wait_for_timeout(300)
    pg.screenshot(path=SHOTS + '/lc103-desktop.png')
    # a mistake: project + deep dive
    pg.evaluate("LC103.open()"); pg.wait_for_timeout(400)
    pg.fill('#lc103-ui textarea[data-f=pgn]', TRAP); pg.select_option('#lc103-ui select[data-f=depth]', 'deep'); pg.click('#lc103-ui [data-m=run]')
    pg.wait_for_function("LC103.cur() && LC103.cur().done && /Student/.test(LC103.cur().label)", timeout=240000); pg.wait_for_timeout(600)
    T = pg.evaluate("LC103.cur().moments.map(m => [m.num, m.san, m.types])")
    out('trap game [Qg5 is a minefield, Nxf7 a blunder]', [any(x[1] == 'Qg5' and 'minefield' in x[2] for x in T), any(x[1] == 'Nxf7' and 'blunder' in x[2] for x in T)])
    bi = pg.evaluate("LC103.cur().moments.filter(m => m.san === 'Nxf7')[0].i")
    pg.click('#lc103-ui [data-m=proj][data-i="%d"]' % bi); pg.wait_for_timeout(400)
    out('video project [made, keeps the game and the move]', pg.evaluate("(() => { const p = LC79.db().list[0]; return [/Nxf7/.test(p.name), p.src && p.src.item && p.src.item.i, !!(p.src && p.src.pgn)]; })()") == [True, bi, True])
    pg.click('#lc103-ui [data-m=deep][data-i="%d"]' % bi); pg.wait_for_timeout(2500)
    out('deep dive [Game-to-Script open on this mistake]', pg.evaluate("[!!document.getElementById('lc79-ai'), /Nxf7/.test((document.querySelector('#lc79-ai #lc79-s2') || {}).textContent || '')]"))
    pg.evaluate("document.querySelector('#lc79-ai [data-a=close]').click()"); pg.wait_for_timeout(600)
    # Game-to-Script hands a game over
    st(pg, "R.querySelector('[data-mb=script]').click(); return 1"); pg.wait_for_timeout(800)
    pg.evaluate("LC103.setUI({depth: 'fast'})"); pg.fill('#lc79-ai textarea[data-f=pgn]', OPERA); pg.click('#lc79-ai [data-a=moments]'); pg.wait_for_timeout(1200)
    out('Game-to-Script button [finder open, game handed over, scan started]', pg.evaluate("[!!document.getElementById('lc103-ui'), /Morphy/.test(document.querySelector('#lc103-ui textarea').value), !!(LC103.cur() && /Morphy/.test(LC103.cur().label))]"))
    pg.wait_for_function("LC103.cur() && LC103.cur().done", timeout=240000)
    pg.keyboard.press('Escape'); pg.wait_for_timeout(400)
    # reload: the scan comes back
    pg.reload(); pg.wait_for_function("!!(" + _SR + ")", timeout=30000); pg.wait_for_timeout(4500)
    st(pg, "R.querySelector('[data-mb-tab=shoot]').click(); return 1"); pg.wait_for_timeout(2000)
    out('after a reload [Showbar back, same game, earlier scans]', [st(pg, "return !R.querySelector('#lc103-sb').hidden"), pg.evaluate("/Morphy/.test(LC103.cur().label)"), pg.evaluate("LC103.scans().length")])
    out('desktop [overflow-x]', pg.evaluate("Math.max(0, document.scrollingElement.scrollWidth - innerWidth)"))
    # recording: the Showbar stays, the stage keeps its size, a jump works mid-take
    st(pg, "R.getElementById('lc54-rec').click(); return 1"); pg.wait_for_timeout(4500)
    r1 = rects(pg); i1 = pg.evaluate("LanckrietStudio.board.idx")
    st(pg, "R.querySelector('#lc103-sb [data-sb=next]').click(); return 1"); pg.wait_for_timeout(400)
    st(pg, "R.querySelector('#lc103-sb [data-sb=fold]').click(); return 1"); pg.wait_for_timeout(300); st(pg, "R.querySelector('#lc103-sb [data-sb=unfold]').click(); return 1"); pg.wait_for_timeout(300)
    rr = rects(pg)
    out('while recording [Showbar shown, a jump, fold and unfold leave the stage and the record bar alone, jumped]', [st(pg, "return !R.querySelector('#lc103-sb').hidden"), rr['stage'] == r1['stage'], rr['dock'] == r1['dock'], pg.evaluate("LanckrietStudio.board.idx") != i1])
    st(pg, "R.getElementById('lc54-rec').click(); return 1"); pg.wait_for_timeout(2500)
    st(pg, "const b = R.querySelector('.rv-later') || R.querySelector('.rv-send'); if (b) b.click(); return 1"); pg.wait_for_timeout(500)
    c.close()
    # phone
    c = mkctx(br, 390, 844, True); pg = c.new_page(); watch(pg, 'lc103-phone'); boot(pg)
    before = rects(pg)
    pg.evaluate("LC103.useScan(LC103.scans().length ? LC103.scans()[0].key : '')")
    pg.evaluate("(async () => { if (!LC103.cur()) await LC103.scan(%r, {depth: 'fast'}); LC103.paint(); })()" % OPERA)
    pg.wait_for_function("LC103.cur() && LC103.cur().done", timeout=240000); pg.wait_for_timeout(1500)
    after = rects(pg); b, d = after['bar'], after['dock']
    out('phone Showbar [shown, under the record bar, inside the screen, dock same, stage same]', [st(pg, "return !R.querySelector('#lc103-sb').hidden"), b[1] >= d[1] + d[3], b[0] >= 0 and b[0] + b[2] <= 390 and b[1] + b[3] <= 844, before['dock'] == d, before['stage'] == after['stage']])
    out('phone owner switcher [buttons not under it, chips padded]', st(pg, "const f = document.getElementById('lc49-float'); if (!f) return 'no switcher'; const fr = f.getBoundingClientRect(); const hit = [...R.querySelectorAll('#lc103-sb .sb-k')].some(b => { const r = b.getBoundingClientRect(); return r.right > fr.left && r.left < fr.right && r.bottom > fr.top && r.top < fr.bottom; }); return [hit, parseInt(getComputedStyle(R.querySelector('#lc103-sb .sb-c')).paddingRight) > 0]"))
    out('phone [toggles in the settings panel, tap targets >= 44 px]', [st(pg, "return getComputedStyle(R.querySelector('#lc103-sb .sb-f')).display"), st(pg, "return [...R.querySelectorAll('#lc103-sb .sb-k, #lc103-sb .sb-i')].every(e => { const r = e.getBoundingClientRect(); return r.height >= 44 && r.width >= 44; })")])
    st(pg, "R.querySelector('#lc103-sb [data-sb=set]').click(); return 1"); pg.wait_for_timeout(300)
    out('phone settings [type toggles, inside the screen]', st(pg, "const p = R.querySelector('#lc103-pop'), r = p.getBoundingClientRect(); return [R.querySelectorAll('#lc103-pop .pp-t').length, r.left >= 0 && r.right <= innerWidth && r.top >= 0]"))
    pg.screenshot(path=SHOTS + '/lc103-phone.png')
    st(pg, "R.querySelector('#lc103-sb [data-sb=set]').click(); return 1")
    pg.evaluate("LC103.open()"); pg.wait_for_timeout(600)
    out('phone finder [overflow-x, buttons >= 44 px]', [pg.evaluate("document.getElementById('lc103-ui').scrollWidth - innerWidth"), pg.evaluate("[...document.querySelectorAll('#lc103-ui .m-b')].filter(b => b.offsetParent).every(b => b.getBoundingClientRect().height >= 44)")])
    pg.screenshot(path=SHOTS + '/lc103-phone-finder.png')
    c.close()
    # unit checks of the pure parts
    c = mkctx(br, 1280, 800); pg = c.new_page(); watch(pg, 'lc103-unit'); pg.goto(APP + '#home'); pg.wait_for_timeout(4000)
    out('instinct [recapture ranks first]', pg.evaluate("(() => { const r = LC103._t.instinct('r1bqkbnr/pppp1ppp/2n5/8/3pP3/5N2/PPP2PPP/RNBQKB1R w KQkq - 0 4', {to: 'd4', captured: 'x'}); return [r[0].san, r[0].tags.indexOf('recapture') >= 0]; })()"))
    out('instinct [the free capture is ranked high, the hanging move low]', pg.evaluate("(() => { const r = LC103._t.instinct('rnbqkbnr/ppp2ppp/8/3pp3/4P3/5N2/PPPP1PPP/RNBQKB1R w KQkq - 0 3', null); const k = s => r.findIndex(x => x.san === s); return [k('Nxe5') < 3, k('Ng5') > k('Nxe5')]; })()"))
    out('sacrifice [Qb8+ Nxb8 Rd8#, a quiet developing move is none]', pg.evaluate("(() => { const g = LC80.scan.parseGame(%r); return [JSON.stringify(LC103._t.sacOf(g.fens[30], ['b3b8','d7b8','d1d8'], 'w')), LC103._t.sacOf(g.fens[2], ['g1f3','b8c6'], 'w')]; })()" % OPERA))
    out('LC103 [same text in lc103.js and app.html, init, Studio hooks, build]', [open(REPO + '/lc103.js', encoding='utf-8').read().rstrip('\n') in open(REPO + '/app.html', encoding='utf-8').read(), 'LC103.init()' in open(REPO + '/app.html', encoding='utf-8').read(), 'data-mb="moments"' in open(REPO + '/lc79.js', encoding='utf-8').read() and 'data-a="moments"' in open(REPO + '/lc79.js', encoding='utf-8').read(), pg.evaluate("LC103.version")])
    c.close(); br.close()
# Game-to-Script: the analysis is the full moment scan, split into mistakes and good moves; project, Load and go to Shoot, the flow card
for w, hh, mob, tag in [(1280, 800, False, 'desktop'), (390, 844, True, 'phone')]:
  with sync_playwright() as p:
    br = p.chromium.launch(args=['--use-fake-ui-for-media-stream', '--use-fake-device-for-media-stream'])
    c = mkctx(br, w, hh, mob); pg = c.new_page(); watch(pg, 'g2s-' + tag)
    pg.goto('http://127.0.0.1:8765/version.json'); pg.evaluate(OWNER); pg.evaluate("localStorage.setItem('lc103-ui', JSON.stringify({depth: 'fast'}))")
    pg.goto(APP + '#studio'); pg.wait_for_function("!!(" + _SR + ")", timeout=30000); pg.wait_for_timeout(3500)
    pg.evaluate("document.querySelectorAll('.sheet-wrap [data-close]').forEach(b => b.click())")
    st(pg, "const f = R.querySelector('.lc31-fmt'); if (f) f.click(); return 1"); pg.wait_for_timeout(500)
    st(pg, "R.querySelector('[data-mb=script]').click(); return 1"); pg.wait_for_timeout(800)
    pg.evaluate("LC79._ai.games = [%r, %r]; LC79.openScript()" % (OPERA, TRAP)); pg.wait_for_timeout(600)
    out(tag + ' g2s [games listed, button, side and depth]', pg.evaluate("[document.querySelectorAll('#lc79-ai [data-a=usegame]').length, document.querySelector('#lc79-ai [data-a=analyse]').textContent, document.querySelector('#lc79-ai select[data-f=side] option').textContent, !!document.querySelector('#lc79-ai select[data-f=depth]')]"))
    pg.click('#lc79-ai [data-a=usegame][data-i="0"]'); pg.wait_for_timeout(3000)
    out(tag + ' g2s scanning [status]', pg.evaluate("document.querySelector('#lc79-ai [data-st]').textContent.slice(0, 16)"))
    pg.wait_for_function("!!document.querySelector('#lc79-ai #lc79-sb')", timeout=240000); pg.wait_for_timeout(800)
    out(tag + ' g2s list [title, mistakes h4, good h4, rows, kind toggles]', pg.evaluate("(() => { const s = document.querySelector('#lc79-ai #lc79-sb').closest('section'); return [s.querySelector('h3').textContent.replace(/\\d+/, 'N'), [...s.querySelectorAll('h4')].map(h => h.textContent.replace(/\\d+/, 'N')), s.querySelectorAll('.lc79-mo').length === LC79._ai.list.length, s.querySelectorAll('.lc79-kt').length]; })()"))
    gi = pg.evaluate("LC79._ai.list.findIndex(x => x.san === 'Qb8+')")
    pg.click('#lc79-ai [data-a=case][data-i="%d"]' % gi); pg.wait_for_timeout(1200)
    out(tag + ' good move case [title, Brilliant line, no cost line, why it matters]', pg.evaluate("(() => { const s = document.querySelector('#lc79-ai #lc79-s2').closest('section'); const t = s.textContent; return [s.querySelector('h3').textContent, /Brilliant/.test(t) && /first choice/.test(t), !/It cost about/.test(t), /Why it matters/.test(t)]; })()"))
    out(tag + ' good move prompt [not a mistake]', pg.evaluate("(() => { const t = LC79.buildPrompt('full'); return [/Instructive good move \\(Brilliant/.test(t), /Crucial mistake/.test(t), /Player: Paul Morphy/.test(t)]; })()"))
    pg.click('#lc79-ai #lc79-s2 ~ * [data-a=mkproj], #lc79-ai section:has(#lc79-s2) [data-a=mkproj]'); pg.wait_for_timeout(500)
    out(tag + ' project [name, kind kept, record bar set to it]', pg.evaluate("(() => { const p = LC79.db().list[0]; return [p.name, p.src.item.kind, localStorage.getItem('lc79-recto') === JSON.stringify(p.id)]; })()"))
    pg.click('#lc79-ai [data-a=toshoot]'); pg.wait_for_timeout(1200)
    out(tag + ' load and go to Shoot [layer closed, board on the move, Shoot tab, Showbar]', [pg.evaluate("!document.getElementById('lc79-ai')"), pg.evaluate("LanckrietStudio.board.idx") == pg.evaluate("LC79._ai.list[%d].i" % gi), pg.evaluate("JSON.parse(localStorage.getItem('lc66-tab'))"), st(pg, "const b = R.querySelector('#lc103-sb'); return !!b && !b.hidden")])
    pg.evaluate("LC79.setStep(2)"); pg.wait_for_timeout(500)
    out(tag + ' recording flow card [good move, tag, rows]', pg.evaluate("(() => { const c = LC79.flow().card; return c ? [c.good, c.tag, c.rows.map(r => r[0])] : null; })()"))
    pg.evaluate("LC79.setStep(1)")
    # a mistake from the second game
    pg.evaluate("LC79.openScript()"); pg.wait_for_timeout(500); pg.click('#lc79-ai [data-a=usegame][data-i="1"]')
    pg.wait_for_function("LC79._ai.list && LC79._ai.list.some(x => x.san === 'Nxf7') && !LC79._ai.busy", timeout=240000); pg.wait_for_timeout(800)
    bi = pg.evaluate("LC79._ai.list.findIndex(x => x.san === 'Nxf7')")
    pg.click('#lc79-ai [data-a=case][data-i="%d"]' % bi); pg.wait_for_timeout(1000)
